/**
 * Kelimenin kök harfini döndürür (Artikel ve parantezleri temizler)
 */
export const getCleanRootLetter = (nl) => {
  if (!nl) return '#';
  const clean = nl
    .toLowerCase()
    .replace(/^(de|het|een)\s+/, '')
    .replace(/[()_.,?!'"-]/g, '')
    .trim();
  const first = clean.charAt(0).toUpperCase();
  return /^[A-Z]$/.test(first) ? first : '#';
};

/**
 * Belirli bir chapter kelimelerini istenen türe göre gruplar:
 * @param {Array} words - Chapter'a ait kelimeler dizisi
 * @param {number} chapterId - Ünite numarası
 * @param {'alphabetical' | 'functional' | 'contextual'} groupType - Gruplama şekli
 */
export const groupChapterWords = (words, chapterId, groupType) => {
  if (!words || words.length === 0) return [];

  // 1. ALFABETİK GRUPLAMA
  if (groupType === 'alphabetical') {
    const sorted = [...words].sort((a, b) => {
      const cleanA = a.nl.toLowerCase().replace(/^(de|het|een)\s+/, '').replace(/[()]/g, '').trim();
      const cleanB = b.nl.toLowerCase().replace(/^(de|het|een)\s+/, '').replace(/[()]/g, '').trim();
      return cleanA.localeCompare(cleanB, 'nl');
    });

    const groupsMap = new Map();
    sorted.forEach(word => {
      const letter = getCleanRootLetter(word.nl);
      if (!groupsMap.has(letter)) {
        groupsMap.set(letter, []);
      }
      groupsMap.get(letter).push(word);
    });

    return Array.from(groupsMap.entries()).map(([letter, items]) => ({
      key: `alpha_${letter}`,
      title: letter,
      icon: 'fa-solid fa-font',
      words: items
    }));
  }

  // 2. FONKSİYONEL (DİLBİLGİSEL) GRUPLAMA
  if (groupType === 'functional') {
    const posOrder = ['verb', 'noun', 'adjective', 'expression', 'pronoun', 'preposition', 'number', 'adverb_conjunction'];
    const groupsMap = new Map();

    words.forEach(word => {
      const meta = WORD_METADATA[word.id];
      const posKey = meta ? meta.pos : 'adverb_conjunction';
      if (!groupsMap.has(posKey)) {
        groupsMap.set(posKey, []);
      }
      groupsMap.get(posKey).push(word);
    });

    const result = [];
    posOrder.forEach(posKey => {
      if (groupsMap.has(posKey) && groupsMap.get(posKey).length > 0) {
        const cat = POS_CATEGORIES[posKey];
        result.push({
          key: `pos_${posKey}`,
          id: posKey,
          title: cat,
          icon: cat.icon,
          badgeBg: cat.badgeBg,
          words: groupsMap.get(posKey)
        });
      }
    });
    return result;
  }

  // 3. CONTEXTUAL (BAĞLAMSAL / TEMATİK) GRUPLAMA
  const themes = CHAPTER_THEMES[chapterId] || [
    { id: 'core_words', tr: 'Temel Kelimeler', en: 'Core Vocabulary', icon: 'fa-solid fa-shapes' }
  ];

  const groupsMap = new Map();
  themes.forEach(t => groupsMap.set(t.id, []));

  words.forEach(word => {
    const meta = WORD_METADATA[word.id];
    let ctxKey = meta ? meta.context : 'core_words';
    if (!groupsMap.has(ctxKey)) {
      ctxKey = 'core_words';
    }
    if (!groupsMap.has(ctxKey)) {
      groupsMap.set(ctxKey, []);
    }
    groupsMap.get(ctxKey).push(word);
  });

  const result = [];
  themes.forEach(theme => {
    const themeWords = groupsMap.get(theme.id) || [];
    if (themeWords.length > 0) {
      result.push({
        key: `ctx_${theme.id}`,
        id: theme.id,
        title: { tr: theme.tr, en: theme.en },
        icon: theme.icon,
        words: themeWords
      });
    }
  });

  return result;
};
